item.command:
/bin/bash -c "node - <<'NODE'
const fs = require('fs');
const path = require('path');
function manifests(root) {
  const dir = path.join(root, 'packages');
  return fs.readdirSync(dir)
    .filter((name) => fs.existsSync(path.join(dir, name, 'package.json')))
    .map((name) => JSON.parse(fs.readFileSync(path.join(dir, name, 'package.json'), 'utf8')));
}
function edges(root) {
  return new Set(manifests(root).flatMap((manifest) =>
    Object.keys(manifest.dependencies || {}).map((dependency) => "'`${manifest.name} -> ${dependency}`)
  ));
}
const base = edges('"'base');
const current = edges('.');
console.log('BASE');
console.log([...base].sort().join('\\n'));
console.log('CURRENT');
console.log([...current].sort().join('\\n'));
console.log('ADDED');
console.log([...current].filter((edge) => "'!base.has(edge)).sort().join('"'\\n') || '(none)');
console.log('REMOVED');
console.log([...base].filter((edge) => "'!current.has(edge)).sort().join('"'\\n') || '(none)');
NODE"

